const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;
const SHA256 = /^[0-9a-f]{64}$/u;
const LIVE_AGENT_STATES = new Set(["creating", "idle", "busy", "stopping"]);
const CONCURRENT_TASK_STATES = new Set(["created", "running"]);
const ORCHESTRATION_READ_CONCURRENCY = 8;
export interface MeshPaths { directory: string; mesh: string; lease: string; epochs: string; agents: string; tasks: string; endpoints: string; watches: string; events: string; reservations: string }
export interface AgentPaths { directory: string; agent: string; status: string; stop: string; events: string; session: string }
export interface TaskPaths { directory: string; request: string; status: string; result: string; cancel: string; usageClaim: string }
export interface LeaseEvidence { pidAlive: boolean; sameSession: boolean; tmuxMatches: boolean }

export function assertId(id: string, label = "ID"): void { if (!UUID.test(id)) throw new Error(`Invalid ${label}: ${id}`); }
export function meshPaths(stateRoot: string, meshId: string): MeshPaths { assertId(meshId, "mesh ID"); const directory = meshDirectory(stateRoot, meshId); return { directory, mesh: join(directory, "mesh.json"), lease: join(directory, "lease.json"), epochs: join(directory, "epochs"), agents: join(directory, "agents"), tasks: join(directory, "tasks"), endpoints: join(directory, "endpoints"), watches: join(directory, "watches"), events: join(directory, "events"), reservations: join(directory, "reservations") }; }
export function agentPaths(stateRoot: string, meshId: string, agentId: string): AgentPaths { assertId(agentId, "agent ID"); const root = meshPaths(stateRoot, meshId); const directory = join(root.agents, agentId); return { directory, agent: join(directory, "agent.json"), status: join(directory, "status.json"), stop: join(directory, "stop.json"), events: join(directory, "events.jsonl"), session: join(directory, "session") }; }
export function taskPaths(stateRoot: string, meshId: string, taskId: string): TaskPaths { assertId(taskId, "task ID"); const directory = join(meshPaths(stateRoot, meshId).tasks, taskId); return { directory, request: join(directory, "request.json"), status: join(directory, "status.json"), result: join(directory, "result.json"), cancel: join(directory, "cancel.json"), usageClaim: join(directory, "usage-claim.json") }; }
export function epochPath(stateRoot: string, meshId: string, epochId: string): string { assertId(epochId, "epoch ID"); return join(meshPaths(stateRoot, meshId).epochs, `${epochId}.json`); }
export function reservationPath(stateRoot: string, meshId: string, reservationId: string): string { assertId(reservationId, "reservation ID"); return join(meshPaths(stateRoot, meshId).reservations, `${reservationId}.json`); }

export async function readJson<T>(path: string): Promise<T> { return JSON.parse(await readFile(path, "utf8")) as T; }
async function optionalJson(path: string): Promise<unknown> { return readJson<unknown>(path).catch(error => (error as NodeJS.ErrnoException).code === "ENOENT" ? undefined : Promise.reject(error)); }
