function validateMesh(value: unknown, expectedMeshId: string): MeshRecord { const raw = record(value, ["meshId", "state", "recoverable", "rootSessionId", "budgets", "createdAt", "updatedAt"], ["rootSessionFile", "rootAttachedAt", "currentEpochId", "closedAt", "budgetMigration"], "mesh record"); id(raw.meshId, "mesh record meshId", expectedMeshId); if (!MESH_STATES.includes(raw.state as never)) throw new Error("mesh record state is invalid"); boolean(raw.recoverable, "mesh record recoverable"); nonempty(raw.rootSessionId, "mesh record rootSessionId"); optionalText(raw.rootSessionFile, "mesh record rootSessionFile"); budgets(raw.budgets, "mesh record budgets"); timestamp(raw.createdAt, "mesh record createdAt"); timestamp(raw.updatedAt, "mesh record updatedAt"); if (raw.rootAttachedAt !== undefined) timestamp(raw.rootAttachedAt, "mesh record rootAttachedAt"); optionalId(raw.currentEpochId, "mesh record currentEpochId"); if (raw.closedAt !== undefined) timestamp(raw.closedAt, "mesh record closedAt"); if (raw.budgetMigration !== undefined) budgetMigration(raw.budgetMigration); if (raw.state === "closed" && raw.closedAt === undefined) throw new Error("closed mesh record requires closedAt"); return value as MeshRecord; }
