    const profiles = Object.fromEntries(Object.entries(object(raw.profiles, "policy epoch profiles")).map(([name, profile]) => [name, validateExecutionProfile(name, profile, `policy epoch profiles.${name}`)]));
    const policies = Object.fromEntries(Object.entries(object(raw.policies, "policy epoch policies")).map(([name, value]) => { const policy = object(value, `policy epoch policies.${name}`); const keys = Object.keys(policy); if (keys.some(key => key !== "roles" && key !== "profiles")) throw new Error(`policy epoch policies.${name} contains unknown keys`); return [name, { roles: policy.roles === undefined ? [] : strings(policy.roles, `policy epoch policies.${name}.roles`), profiles: policy.profiles === undefined ? [] : strings(policy.profiles, `policy epoch policies.${name}.profiles`) }]; }));
