function validateReservation(value: unknown, meshId: string, reservationId: string): BudgetReservation { const raw = record(value, ["meshId", "reservationId", "kind", "state", "liveSlots", "taskSlots", "lifetimeTasks", "createdAt", "updatedAt"], ["agentId", "taskId", "committedAt", "releasedAt", "releaseReason"], "budget reservation"); id(raw.meshId, "reservation meshId", meshId); id(raw.reservationId, "reservation reservationId", reservationId); if (raw.kind !== "new-agent-task" && raw.kind !== "existing-agent-task") throw new Error("reservation kind is invalid"); if (!RESERVATION_STATES.includes(raw.state as never)) throw new Error("reservation state is invalid"); const expectedLive = raw.kind === "new-agent-task" ? 1 : 0; if (raw.liveSlots !== expectedLive || raw.taskSlots !== 1 || raw.lifetimeTasks !== 1) throw new Error("reservation slots do not match kind"); optionalId(raw.agentId, "reservation agentId"); optionalId(raw.taskId, "reservation taskId"); timestamp(raw.createdAt, "reservation createdAt"); timestamp(raw.updatedAt, "reservation updatedAt"); if (raw.committedAt !== undefined) timestamp(raw.committedAt, "reservation committedAt"); if (raw.releasedAt !== undefined) timestamp(raw.releasedAt, "reservation releasedAt"); optionalText(raw.releaseReason, "reservation releaseReason"); return value as BudgetReservation; }
export function validateStopReason(value: unknown, label = "stop reason"): string { if (typeof value !== "string") throw new Error(`${label} must be a string`); const reason = value.trim(); const bytes = Buffer.byteLength(reason, "utf8"); if (bytes < 1 || bytes > 512) throw new Error(`${label} must be 1-512 UTF-8 bytes after trimming`); return reason; }
